#import <Cocoa/Cocoa.h>
#import <CoreGraphics/CoreGraphics.h>
int main(){@autoreleasepool{NSMutableArray* out=[NSMutableArray array];for(NSScreen* s in NSScreen.screens){CGDirectDisplayID d=[s.deviceDescription[@"NSScreenNumber"] unsignedIntValue];NSArray* modes=(__bridge_transfer NSArray*)CGDisplayCopyAllDisplayModes(d,NULL);NSMutableSet* sizes=[NSMutableSet set];for(id item in modes){CGDisplayModeRef m=(__bridge CGDisplayModeRef)item;size_t w=CGDisplayModeGetWidth(m),h=CGDisplayModeGetHeight(m);if(w<=2048&&h<=2048&&w>=1200&&h>=700)[sizes addObject:[NSString stringWithFormat:@"%zux%zu",w,h]];}[out addObject:@{@"id":@(d),@"name":s.localizedName,@"modes":[[sizes allObjects] sortedArrayUsingSelector:@selector(compare:)]}];}NSData* data=[NSJSONSerialization dataWithJSONObject:out options:NSJSONWritingPrettyPrinted error:nil];puts([[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding].UTF8String);}}
